# v27/v28: KPI builder, new visuals, drill-through, schedules, templates, view-only dashboards, documents library.
# Offline mode (sample organisation). Run: python3 tests/e2e/analytics_docs_e2e.py
import asyncio, os, csv, io
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
from playwright.async_api import async_playwright
EXE = os.environ.get('CHROME') or (lambda d: d if os.path.exists(d) else None)('/opt/pw-browsers/chromium_headless_shell-1208/chrome-headless-shell-linux64/chrome-headless-shell')
WEB = os.environ.get('SF_WEB', 'public')
RES = []
def ok(n, c, x=''): RES.append((n, bool(c))); print(('PASS ' if c else 'FAIL ') + n, '' if c else str(x)[:300], flush=True)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=EXE); ctx = await b.new_context(viewport={'width':1400,'height':900}, accept_downloads=True); pg = await ctx.new_page()
        await pg.add_init_script(path=os.path.join(ROOT, 'tests/e2e/hook.js')); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto('file://' + ROOT + '/' + WEB + '/index.html'); await pg.wait_for_selector('#sf-user')
        S = lambda e: pg.evaluate(f"(() => {{ const s = window.__app.state; return {e}; }})()"); V = lambda e: pg.evaluate(f"(() => {{ const v = window.__app.renderVals(); return {e}; }})()"); W = lambda ms=300: pg.wait_for_timeout(ms)
        async def dl(js):
            async with pg.expect_download() as d: await pg.evaluate(js)
            f = await (await d.value).path(); return open(f, encoding='utf-8-sig').read()
        await pg.locator('.sf-demo2-b').filter(has_text='Admin').click(); await pg.get_by_role('button', name='Login', exact=True).click(); await W(1000)

        # ---------- custom KPI values, recounted independently from the raw batches ----------
        rc = await pg.evaluate("""(() => { const s = window.__app.state, ttB = new Map(s.ttypes.map(t => [t.id, t])); let hr0 = 0, abs1 = 0, mk1 = 0, pr1 = 0;
          s.batches.forEach(b => { const tt = ttB.get(b.type), d1 = tt ? trainDays(b.start, 1, holSetFor(s.holidays, b))[0] : null;
            b.trainees.forEach(n => { const u = s.users.find(x => x.name === n) || {}; if (b.traineeType === 'New Hire' && b.start <= TODAY_KEY && u.joined && u.joined <= b.start) hr0++; const a = d1 && ((b.att || {})[d1] || {})[n]; if (a) { mk1++; if (a === 'A') abs1++; if (a === 'P' || a === 'L') pr1++; } }); });
          return { hr0, abs1, mk1, pr1 }; })()""")
        T = await pg.evaluate("(() => { const s = window.__app.state; Dash.useKpis(s.dash.kpis); const t = Dash.train(s, s.dash.slicers).tot; return { hr0: t.hrms0, abs1: t.dA[1], mk1: t.dM[1], pr1: t.dP[1], k1: Dash.measure('train', t, 'k:kp1'), k2: Dash.measure('train', t, 'k:kp2'), k3: Dash.measure('train', t, 'k:kp3') }; })()")
        ok('HRMS joined by day 0 matches an independent recount', T['hr0'] == rc['hr0'], (T, rc))
        ok('day-1 absent / marked / present match an independent recount', (T['abs1'], T['mk1'], T['pr1']) == (rc['abs1'], rc['mk1'], rc['pr1']), (T, rc))
        ok('KPI "joined on day 0 (HRMS) minus absent on day 1" = recount', T['k1'] == rc['hr0'] - rc['abs1'], (T['k1'], rc))
        ok('KPI day-1 absence rate = absent ÷ marked × 100', abs(T['k2'] - rc['abs1'] / rc['mk1'] * 100) < 1e-9, T['k2'])
        ok('KPI day-1 show-up = present ÷ HRMS joiners × 100', abs(T['k3'] - rc['pr1'] / rc['hr0'] * 100) < 1e-9, T['k3'])

        # ---------- KPI builder: validation and save ----------
        await pg.evaluate("window.__app.go('kpis', { adminView:true })"); await W()
        await pg.get_by_role('button', name='+ New KPI').click(); await W()
        await pg.locator('.kp-ed input').first.fill('Absent days 1 to 3'); await pg.locator('.kp-ed textarea').fill('ABSENT_DAY(1) + ABSENT_DAY(2) + absent'); await W()
        ok('unknown field reported while typing', 'Unknown field' in (await V("v.kECheck")))
        await pg.locator('.kp-ed textarea').fill('alert(document.cookie)'); await W()
        ok('code in a formula is refused', not await V("v.kEOk") and '“.” is not allowed' in (await V("v.kECheck")), await V("v.kECheck"))
        await pg.locator('.kp-ed textarea').fill('constructor(1)'); await W()
        ok('unknown functions are refused', not await V("v.kEOk") and 'Unknown function' in (await V("v.kECheck")))
        await pg.locator('.kp-ed textarea').fill('ABSENT_DAY(1) + ABSENT_DAY(2) + ABSENT_DAY(3)'); await W()
        ok('valid formula previews a value', await V("v.kEOk") and (await V("v.kEPreview")) not in ('—', ''))
        await pg.get_by_role('button', name='Save KPI').click(); await W()
        kid = await S("(s.dash.kpis.find(k => k.code === 'absent_days_1_to_3') || {}).id")
        ok('KPI saved with a code made from its name', bool(kid))
        ok('saved KPI has no extra (compiled) fields', await S(f"Object.keys(s.dash.kpis.find(k => k.id === '{kid}')).every(k => ['id','code','name','src','formula','fmt','dp','dir','green','amber','desc','by','at'].includes(k))"))
        await pg.evaluate("window.__app.setState({ kpiEd: { name:'Loop A', code:'loop_a', src:'train', formula:'absent_days_1_to_3 + 1', fmt:'n', dp:'', dir:'up', green:'', amber:'', desc:'', err:'' } })"); await W()
        await pg.evaluate("window.__app.renderVals().kESave()"); await W()
        await pg.evaluate("window.__app.setState(st => ({ dash: { ...st.dash, kpis: st.dash.kpis.map(k => k.code === 'absent_days_1_to_3' ? { ...k, formula: 'loop_a + 1' } : k) } }))")
        loop = await pg.evaluate("(() => { const s = window.__app.state; Dash.useKpis(s.dash.kpis); return Dash.measure('train', Dash.train(s, s.dash.slicers).tot, 'k:' + s.dash.kpis.find(k => k.code === 'loop_a').id); })()")
        ok('a loop between KPIs gives no value instead of hanging', loop is None)
        await pg.evaluate(f"window.__app.setState(st => ({{ dash: {{ ...st.dash, kpis: st.dash.kpis.filter(k => k.code !== 'loop_a').map(k => k.id === '{kid}' ? {{ ...k, formula: 'ABSENT_DAY(1) + ABSENT_DAY(2) + ABSENT_DAY(3)' }} : k) }} }}))")
        await pg.evaluate("window.__app.setState({ kpiEd: { name:'People no day', code:'p_day', src:'hr', formula:'ABSENT_DAY(1)', fmt:'n', dp:'', dir:'up', green:'', amber:'', desc:'', err:'' } })"); await W()
        ok('attendance functions refused outside the Training dataset', 'Training dataset only' in (await V("v.kECheck")))
        await pg.evaluate("window.__app.setState({ kpiEd: { name:'Bad target', code:'bad_t', src:'train', formula:'joined', fmt:'n', dp:'', dir:'up', green:'5', amber:'9', desc:'', err:'' } })"); await pg.evaluate("window.__app.renderVals().kESave()"); await W()
        ok('inconsistent RAG thresholds refused', 'green must be at least amber' in (await S("s.kpiEd.err")))
        await pg.evaluate("window.__app.setState({ kpiEd:null })")
        ok('KPI used by a template cannot be deleted', True)
        await pg.evaluate("window.__app.renderVals().kpiRows.find(k => k.code === 'day1_absence_rate').del()"); await W()
        ok('…and stays (used in templates)', await S("s.dash.kpis.some(k => k.code === 'day1_absence_rate')"))

        # ---------- new dashboard from the Induction template, every new visual renders ----------
        await pg.evaluate("window.__app.go('dashboard', { adminView:true, dbBoard:'b1' })"); await W()
        await pg.evaluate("window.__app.renderVals().dbNewBoard()"); await W()
        await pg.evaluate("window.__app.setState(st => ({ dbNew: { ...st.dbNew, name: 'Induction QA', from: 'tpl:t_induction' } }))"); await pg.evaluate("window.__app.renderVals().dbNCreate()"); await W(600)
        await pg.evaluate("window.__app.renderVals().dbSave()"); await W(600)
        vis = await V("v.dbVisuals.map(x => ({ t: x.title, kpi: x.isKpi, kv: x.kv, rag: x.kRag, g: x.isGauge, gv: x.gv, h: x.isHeat, cells: (x.hRows || []).length, tb: x.isTable, rows: (x.tRows || []).length }))")
        ok('template board created and saved', await S("s.dash.boards.some(b => b.name === 'Induction QA') && !s.dash.edit"))
        ok('custom KPI cards show values and RAG', any(x['kpi'] and x['rag'] for x in vis) and all(x['kv'] not in (None, '', '—') for x in vis if x['kpi']), vis)
        ok('gauge renders', any(x['g'] and x['gv'] not in ('', '—') for x in vis), vis)
        ok('two-dimension heat map renders rows', any(x['h'] and x['cells'] > 1 for x in vis), vis)
        ok('table with chosen KPI columns renders', any(x['tb'] and x['rows'] > 1 for x in vis), vis)
        await pg.evaluate("window.__app.renderVals().dbNewBoard()"); await W()
        await pg.evaluate("window.__app.setState(st => ({ dbNew: { ...st.dbNew, name: 'Trainer QA', from: 'tpl:t_trainer' } }))"); await pg.evaluate("window.__app.renderVals().dbNCreate()"); await W(600); await pg.evaluate("window.__app.renderVals().dbSave()"); await W(600)
        rad = await V("v.dbVisuals.find(x => x.isRadar)")
        ok('spider web: 5 trainers × 5 spokes', rad and len(rad['rSeries']) == 5 and len(rad['rSpokes']) == 5, rad and (len(rad['rSeries']), len(rad['rSpokes'])))
        await pg.screenshot(path=os.path.join(ROOT, 'tests/e2e/_trainer.png'), full_page=True) if os.environ.get('SF_SHOTS') else None
        await pg.evaluate("window.__app.renderVals().dbNewBoard()"); await W()
        await pg.evaluate("window.__app.setState(st => ({ dbNew: { ...st.dbNew, name: 'People QA', from: 'tpl:t_people' } }))"); await pg.evaluate("window.__app.renderVals().dbNCreate()"); await W(600); await pg.evaluate("window.__app.renderVals().dbSave()"); await W(600)
        pv = await V("v.dbVisuals.map(x => ({ kpi: x.isKpi, kv: x.kv, tree: x.isTree, n: (x.tiles || []).length }))")
        n_users = await S("s.users.filter(u => u.status !== 'Deactivated').length")
        ok('People (HRMS) KPI = current people (active + invited)', pv[0]['kv'] == f"{n_users:,}", (pv[0], n_users))
        ok('treemap renders tiles', any(x['tree'] and x['n'] > 1 for x in pv), pv)

        # ---------- drill-through matches the number on the chart ----------
        await pg.evaluate("window.__app.setState({ dbBoard:'b1' })"); await W(400)
        donut = await V("v.dbVisuals.find(x => x.isDonut)")
        od = [x for x in donut['slices'] if x['l'] == 'Overdue'][0]
        await pg.evaluate("window.__app.renderVals().dbVisuals.find(x => x.isDonut).slices.find(x => x.l === 'Overdue').drill()"); await W(1500)
        cnt = await V("v.dbDrillCount")
        ok('drill-through count = the slice value (Overdue)', cnt.startswith(od['v'].split(' ')[0]), (cnt, od['v']))
        ok('drill rows are paged (50)', await V("v.dbDrillRows.length") == 50)
        ok('drill columns carry no e-mail or phone', all(h not in ('Email', 'Phone', 'Contact number') for h in await V("v.dbDrillHead.map(h => h.t)")))
        text = await dl("window.__app.renderVals().dbDrillCsv()")
        ok('drill CSV has every record', len(text.strip().split('\n')) - 1 == int(od['v'].replace(',', '').split(' ')[0]), len(text.split('\n')))
        await pg.evaluate("window.__app.setState({ dbDrill:null })")

        # ---------- schedules: only the organisation's own domains ----------
        await pg.evaluate("window.__app.renderVals().dbSchedOpenFn()"); await W(); await pg.evaluate("window.__app.renderVals().dbSchedNew()"); await W()
        await pg.evaluate("window.__app.setState(st => ({ dbSched: { form: { ...st.dbSched.form, to: 'boss@example.com, leak@gmail.com' } } }))"); await pg.evaluate("window.__app.renderVals().dbSFSave()"); await W()
        ok('schedule to an outside domain refused', 'outside your organisation' in (await S("s.dbSched.form.err")))
        await pg.evaluate("window.__app.setState(st => ({ dbSched: { form: { ...st.dbSched.form, to: 'boss@example.com', err:'' } } }))"); await pg.evaluate("window.__app.renderVals().dbSFSave()"); await W()
        ok('internal schedule saved', await S("(s.dash.schedules || []).some(x => x.to.includes('boss@example.com') && x.board === 'b1')"))
        text = await dl("window.__app.renderVals().dbSchedList[0].run()")
        ok('Run now downloads the dashboard data', text.startswith('Visual,Source'), text[:60])
        await pg.evaluate("window.__app.setState({ dbSched:null })")

        # ---------- Power BI data: no names / e-mails / phones ----------
        text = await dl("window.__app.renderVals().dbPbiTrain()")
        head = next(csv.reader(io.StringIO(text)))
        ok('Power BI training facts: no name, e-mail or phone columns', not any(h in ('Name', 'Email', 'Phone', 'Contact number') for h in head), head)
        n_part = await S("Dash.train(s, s.dash.slicers).tot.participants")
        ok('Power BI training facts: one row per participant', len(list(csv.reader(io.StringIO(text)))) - 1 == n_part)

        # ---------- CSV formula-injection guard ----------
        g = await pg.evaluate("[csvSafe('=HYPERLINK(\"http://x\")'), csvSafe('+1+1'), csvSafe('@SUM(A1)'), csvSafe('-5'), csvSafe('-2.5%'), csvSafe(-3), csvSafe('Maya')]")
        ok('CSV: formulas neutralised, numbers kept', g == ["'=HYPERLINK(\"http://x\")", "'+1+1", "'@SUM(A1)", '-5', '-2.5%', '-3', 'Maya'], g)

        # ---------- view-only dashboards for a role ----------
        await pg.evaluate("""window.__app.setState(st => ({ roles: st.roles.map(r => r.id === 'r_trainer' ? { ...r, perms: { ...r.perms, dashView: true } } : r),
          dash: { ...st.dash, boards: st.dash.boards.map(b => b.name === 'Trainer QA' ? { ...b, audience: ['r_trainer'] } : b) } }))""")
        await pg.evaluate("window.__app.go('home', { role:'instructor', meName:'Daniel Reyes', meRole:'instructor', adminView:false })"); await W(500)
        await pg.evaluate("window.__app.go('dashboard', { adminView:true })"); await W(800)
        ok('viewer can open dashboards', await V("v.isDash && !v.isDenied"))
        names = await V("v.dbBoards.map(b => b.label)")
        ok('viewer sees boards shared with everyone and with their role', 'Trainer QA' in names and 'Learning overview' in names, names)
        await pg.evaluate("window.__app.setState(st => ({ dash: { ...st.dash, boards: st.dash.boards.map(b => b.name === 'People QA' ? { ...b, audience: ['r_admin'] } : b) } }))"); await W()
        ok('viewer does not see a board shared with another role', 'People QA' not in await V("v.dbBoards.map(b => b.label)"))
        ok('viewer: no Customise, New, Schedule, Power BI, record CSV', not any(await V("[v.dbCanCustomise, v.dbSchedCan, v.dbPbiCan, v.dbDrillCanCsv]")))
        await pg.evaluate("window.__app.renderVals().dbToggleEdit()"); await W()
        ok('viewer cannot switch to edit mode', not await S("s.dash.edit"))
        await pg.evaluate("window.__app.go('kpis', { adminView:true })"); await W()
        ok('viewer cannot open the KPI builder', await V("v.isDenied"))
        await pg.evaluate("window.__app.go('training', { adminView:true })"); await W()
        ok('viewer cannot open Training overview & MIS (needs the full permission)', await V("v.isDenied"))

        # ---------- documents: learner ----------
        await pg.evaluate("window.__app.go('home', { role:'learner', meName:'Maya Okafor', meRole:'learner', adminView:false })"); await W(500)
        ok('Documents is in the menu', 'Documents' in await V("v.navItems.map(n => n.label)"))
        await pg.evaluate("window.__app.go('docs')"); await W(500)
        titles = await V("v.docsRows.map(d => d.title)")
        ok('learner sees documents for everyone, not the trainer SOP', 'Induction Day-1 SOP' not in titles and 'Code of Conduct' in titles, titles)
        notif = await V("v.notifs.map(n => n.t)")
        ok('required reading appears in the bell', any(t.startswith('Required reading:') for t in notif), notif)
        r = await V("v.docsRows.find(d => d.title === 'Information Security Policy')")
        ok('required document starts as not opened', r['canAck'] and not r['ackReady'], r)
        await pg.evaluate("window.__app.renderVals().docsRows.find(d => d.title === 'Information Security Policy').ack()"); await W()
        ok('cannot acknowledge before opening', await S("!((s.docAck['Maya Okafor'] || {}).d1 || {}).ackAt"))
        # v41.7: documents open in the LMS's own viewer (so the view is always recorded); no new tab
        await pg.evaluate("window.__app.renderVals().docsRows.find(d => d.title === 'Information Security Policy').open()"); await W()
        ok('Open shows the file in the in-app viewer', await S("s.docView === 'd1'"), await S("s.docView"))
        await pg.evaluate("window.__app.setState({ docView: null })"); await W()
        await pg.evaluate("window.__app.renderVals().docsRows.find(d => d.title === 'Information Security Policy').ack()"); await W()
        ok('acknowledged after opening, for the current version', await S("s.docAck['Maya Okafor'].d1.ackV === 2"))
        ok('view-only document has no download button', await V("v.docsRows.find(d => d.title === 'Workplace Safety Handbook').canDl === false"))
        ok('links are restricted to safe schemes', await pg.evaluate("[Docs.safeUrl('javascript:alert(1)'), Docs.safeUrl('data:text/html,x'), Docs.safeUrl('http://x'), Docs.safeUrl('assets/../../etc'), Docs.safeUrl('https://x.supabase.co/a'), Docs.safeUrl('assets/docs/a.pdf')]") == ['', '', '', '', 'https://x.supabase.co/a', 'assets/docs/a.pdf'])
        await pg.evaluate("window.__app.go('docAdmin', { adminView:true })"); await W()
        ok('learner cannot open the documents library management', await V("v.isDenied"))

        # ---------- documents: manager ----------
        await pg.evaluate("window.__app.go('home', { role:'admin', meName:'Lena Fischer', meRole:'admin', adminView:false })"); await W(400)
        await pg.evaluate("window.__app.go('docAdmin', { adminView:true })"); await W(400)
        await pg.get_by_role('button', name='+ Upload document').click(); await W()
        fi = pg.locator('.ovl-28 input[type=file]')
        await fi.set_input_files(files=[{ 'name': 'leave-policy.pdf', 'mimeType': 'application/pdf', 'buffer': b'MZ\x90\x00 not a pdf at all' }]); await W(600)
        ok('renamed non-PDF refused by content check', 'does not match' in (await S("s.docEd.err")), await S("s.docEd.err"))
        await fi.set_input_files(files=[{ 'name': 'run.svg', 'mimeType': 'image/svg+xml', 'buffer': b'<svg onload=alert(1)>' }]); await W(300)
        ok('SVG refused', 'Upload a PDF' in (await S("s.docEd.err")))
        pdf = open(os.path.join(ROOT, 'public/assets/docs/code-of-conduct.pdf'), 'rb').read()
        await fi.set_input_files(files=[{ 'name': 'leave-policy.pdf', 'mimeType': 'application/pdf', 'buffer': pdf }]); await W(600)
        await pg.locator('.ovl-28 input').first.fill('Leave Policy'); await W()
        await pg.evaluate("window.__app.setState(st => ({ docEd: { ...st.docEd, audience: ['Learner'], mandatory: true } }))"); await W()
        await pg.evaluate("window.__app.renderVals().dESave()"); await W(500)
        ok('real PDF uploaded and published', await S("s.docs.some(d => d.title === 'Leave Policy' && d.status === 'Published' && d.code === 'DOC-005' && d.versions[0].file.src.startsWith('blob:'))"))
        await pg.evaluate("window.__app.renderVals().docLib.find(d => d.title === 'Leave Policy').newVer()"); await W()
        await pg.locator('.ovl-28 input[type=file]').set_input_files(files=[{ 'name': 'leave-policy-v2.pdf', 'mimeType': 'application/pdf', 'buffer': pdf }]); await W(600)
        await pg.evaluate("window.__app.renderVals().dESave()"); await W()
        ok('new version needs a change note', 'what changed' in (await S("s.docEd.err")).lower())
        await pg.evaluate("window.__app.setState(st => ({ docEd: { ...st.docEd, note: 'Carry-forward rule updated' } }))"); await pg.evaluate("window.__app.renderVals().dESave()"); await W()
        ok('version 2 kept with version 1, everyone acknowledges again', await S("(d => d.cur === 2 && d.versions.length === 2 && d.ackFrom === 2)(s.docs.find(d => d.title === 'Leave Policy'))"))
        await pg.evaluate("window.__app.renderVals().docLib.find(d => d.title === 'Workplace Safety Handbook').archive()"); await W()
        await pg.evaluate("window.__app.go('home', { role:'learner', meName:'Maya Okafor', meRole:'learner', adminView:false })"); await W(300); await pg.evaluate("window.__app.go('docs')"); await W(300)
        titles = await V("v.docsRows.map(d => d.title)")
        ok('archived document hidden from learners; new one shown', 'Workplace Safety Handbook' not in titles and 'Leave Policy' in titles, titles)
        await pg.evaluate("window.__app.setState(st => ({ docs: st.docs.map(d => d.title === 'Code of Conduct' ? { ...d, expiry: '2026-01-31' } : d.title === 'Leave Policy' ? { ...d, effective: '2099-01-01' } : d) }))"); await W()
        titles = await V("v.docsRows.map(d => d.title)")
        ok('expired and not-yet-effective documents hidden', 'Code of Conduct' not in titles and 'Leave Policy' not in titles, titles)

        ok('NO JS ERRORS', not errs, errs)
        print('\nSUMMARY', sum(1 for _, c in RES if c), '/', len(RES)); await b.close()
asyncio.run(main())
